command:
env -u PYTHONPATH ../../../.venv/bin/python -c import importlib, importlib.metadata, json, os
names=['modules','app.main']
out={'python':__import__('sys').version,'PYTHONPATH_present':bool(os.environ.get('PYTHONPATH')),'imports':[]}
for name in names:
 try:
  m=importlib.import_module(name); out['imports'].append({'module':name,'ok':True,'file':getattr(m,'__file__',None)})
 except Exception as e: out['imports'].append({'module':name,'ok':False,'exception':type(e).__name__,'message':str(e)})
try:
 d=importlib.metadata.distribution('smash-suite'); out['distribution']={'installed':True,'version':d.version,'requires_python':d.metadata.get('Requires-Python'),'root':str(d.locate_file(''))}
except Exception as e: out['distribution']={'installed':False,'exception':type(e).__name__,'message':str(e)}
print(json.dumps(out,ensure_ascii=False))
